// Generated by creator/tools/sync-rules.mjs. Edit demo/action-result-events.js instead.
// Native block results distinguish action text from the fan animation and the
// following payout. Derive the presentation from actual local Round deltas.
export const ACTION_RESULT_TIMING={hu:1030,qgh:1030,zimo:1120,peng:1130,gang:1030,payoutShow:820,payoutLock:1000};
export function snapshotActionResult(round){
 return {phase:round.phase,turn:round.turn,huEventCount:round.huEvents?.length||0,scores:round.scores.slice(),melds:round.melds.map(groups=>groups.map(group=>({...group}))),redKongCounts:round.redKongs?.map(h=>h.length)||[0,0,0,0],kongPaymentCount:round.kongPayments?.length||0};
}
export function actionResultEvents(before,round){
 const huEvents=(round.huEvents||[]).slice(before.huEventCount),actions=[];
 for(let seat=0;seat<4;seat++)for(let group=0;group<round.melds[seat].length;group++){
  const current=round.melds[seat][group],previous=before.melds[seat][group];
  if(previous?.type===current.type&&previous?.value===current.value)continue;
  const gang=current.type!=='peng',gangType=current.type==='dark'?'concealed':current.type==='add'?'patched':'exposed';
  actions.push({seat,group,tile:current.value,action:gang?'gang':'peng',nativeEvent:gang?'ANIM_GANG':'ANIM_PENG',gangType:gang?gangType:null,ambient:gang?(gangType==='concealed'?'rain':'wind'):null});
 }
 for(let seat=0;seat<4;seat++)if((round.redKongs?.[seat]?.length||0)>(before.redKongCounts?.[seat]||0))actions.push({seat,tile:51,action:'gang',nativeEvent:'ANIM_GANG',gangType:'red',ambient:null});
 for(const event of huEvents){
  const action=event.selfDraw?'zimo':before.phase==='rob'?'qgh':'hu';
  actions.push({seat:event.seat,from:event.from,tile:event.tile,selfDraw:event.selfDraw,action,nativeEvent:action==='zimo'?'ANIM_ZIMO':action==='qgh'?'ANIM_QGH':'ANIM_HU',fan:{...event.fan},deltas:event.deltas.slice(),huEvent:event});
 }
 const deltas=round.scores.map((score,seat)=>score-before.scores[seat]);
 const otherDeltas=deltas.map((score,seat)=>score-huEvents.reduce((sum,event)=>sum+event.deltas[seat],0));
 return {actions,huEvents,deltas,otherDeltas,kongPayments:(round.kongPayments||[]).slice(before.kongPaymentCount),roundEnded:before.phase!=='end'&&round.phase==='end',actionLockMs:actions.reduce((max,event)=>Math.max(max,ACTION_RESULT_TIMING[event.action]||0),0)};
}
